    private static int FrozenDispatch128(object message)
        => Frozen128.TryGetValue(message.GetType(), out int value) ? value : -1;

    /// <summary>Returns the type-pattern dispatcher for the given message-count size.</summary>
    public static Func<object, int> TypePatternDispatcher(int size) => size switch
    {
        4 => TypePattern4,
        8 => TypePattern8,
        16 => TypePattern16,
        32 => TypePattern32,
        64 => TypePattern64,
        128 => TypePattern128,
        _ => throw new ArgumentOutOfRangeException(nameof(size)),
    };

    /// <summary>Returns the frozen-dictionary dispatcher for the given message-count size.</summary>
    public static Func<object, int> FrozenDispatcher(int size) => size switch
    {
        4 => FrozenDispatch4,
        8 => FrozenDispatch8,
        16 => FrozenDispatch16,
        32 => FrozenDispatch32,
        64 => FrozenDispatch64,
        128 => FrozenDispatch128,
        _ => throw new ArgumentOutOfRangeException(nameof(size)),
    };

    /// <summary>Returns a mid-chain message — the average-case lookup for the type-pattern chain.</summary>
    public static object RepresentativeMessage(int size) => size switch
    {
        4 => new DispatchMsg2(),
        8 => new DispatchMsg4(),
        16 => new DispatchMsg8(),
        32 => new DispatchMsg16(),
        64 => new DispatchMsg32(),
        128 => new DispatchMsg64(),
        _ => throw new ArgumentOutOfRangeException(nameof(size)),
    };
